contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking the caller address (simulated by trying calls
    // from this contract; since InvMutTest is the msg.sender for calls, we simulate
    // different outcomes by performing calls and observing reverts and owner getter.)
    function run(address newOwner, bool attemptByAdmin) public payable {
        require(newOwner != address(0));
        // Read the owner before any mutation
        address ownerBefore = c.owner();

        bool reverted;
        bool ret;

        // We need to simulate two cases: if attemptByAdmin is true, the call must succeed
        // only if this contract is admin of c. Since admin was set to the deploying account
        // of C (the test harness), and the checker deploys a fresh C and then passes it to
        // this test, the admin is the deployer of C, not InvMutTest. Therefore attempting
        // to call setOwner from this contract should revert in normal (non-admin) case.
        // To produce a general rule that covers both possibilities, we attempt the call
        // and record whether it reverted. Then we assert the logical relation between
        // revert flag and observed owner change / return value.

        // Attempt the state-changing call and catch reverts
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
        } catch {
            reverted = true;
            ret = false;
        }

        address ownerAfter = c.owner();

        // General rule asserted:
        // - If the call reverted then owner must be unchanged and ret==false.
        // - If the call did not revert then it must have returned true and owner must equal newOwner.
        assert( (reverted && ownerAfter == ownerBefore && ret == false) || (!reverted && ret == true && ownerAfter == newOwner) );
    }

    receive() external payable {}
}

